function servicePage(s){
 const related=SERVICES.filter(x=>x.slug!==s.slug&&x.group===s.group).slice(0,3);
 let main=pageHero(s.tag,s.headline,s.intro,s.symbol)+
 '<section class="section white"><div class="container content-grid"><article class="prose">'+s.sections.map(sec=>'<h2>'+sec[0]+'</h2>'+sec[1].map(p=>'<p>'+p+'</p>').join("")+(sec[2]?'<ul>'+sec[2].map(x=>'<li>'+x+'</li>').join("")+'</ul>':"")).join("")+'</article><aside class="aside-card"><span class="pill">Before you go further</span><h3>Start with the full picture.</h3><p>Explore a budget estimate, read a practical guide or try our preview questionnaire. None of these are approval decisions or actual application submissions.</p><div class="actions">'+btn("/tools","Use money tools","primary")+(s.group==="Other options"?btn("/tools","Use planning tools","outline"):btn("/apply?type="+(s.group==="Loans"?"loan":"debt"),"Questionnaire demo","outline"))+'</div></aside></div></section>'+
 '<section class="section mint-bg"><div class="container">'+heading("KNOW BEFORE YOU DECIDE","Common questions about "+s.name.toLowerCase()+".")+faqBlock(s.faq)+'</div></section>'+
 '<section class="section white"><div class="container">'+heading("KEEP EXPLORING","You might also want to know.")+'<div class="grid cols-3">'+cards(related.length?related:SERVICES.slice(0,3))+'</div></div></section>';
 shell(main);
}
function guideCards(items){return items.map(g=>'<article class="guide-card"><div><div class="guide-cover"><span style="font-size:.82rem;font-weight:800">'+g.category+'</span><span aria-hidden="true">'+g.symbol+'</span></div><h3>'+g.title+'</h3><p>'+g.excerpt+'</p></div><div class="guide-bottom"><span>'+g.read+'</span>'+link("/guides/"+g.slug,"Read guide ↗")+'</div></article>').join("")}
function guides(){
 shell(pageHero("INFORMATION HUB","Good money decisions start with good questions.","Short, straightforward reads for South African consumers. No exaggerated claims, no hidden offers.","◷")+
 '<section class="section white"><div class="container"><div class="field" style="max-width:430px"><label for="guide-search">Search topics</label><input id="guide-search" class="input" type="search" placeholder="Try: debt review, budget, credit..." autocomplete="off"></div><div id="guide-results" class="grid cols-3" aria-live="polite">'+guideCards(GUIDES)+'</div></div></section>');
 $("#guide-search").addEventListener("input",e=>{let q=e.target.value.toLowerCase().trim();let results=GUIDES.filter(g=>(g.title+" "+g.excerpt+" "+g.category).toLowerCase().includes(q));let n=$("#guide-results");n.innerHTML=results.length?guideCards(results):'<p class="notice">No guides found. Try a different topic.</p>';n.querySelectorAll('a[data-link]').forEach(a=>a.addEventListener("click",e=>{e.preventDefault();navigate(a.getAttribute("href"))}))});
}
function article(g){
 let content=pageHero("INFORMATION HUB · "+g.category,g.title,g.excerpt,g.symbol)+
 '<section class="section white"><div class="container content-grid"><div class="prose"><p class="pill">'+g.read+' · Educational guide</p>'+g.sections.map((s,i)=>'<h2>'+(i+1)+'. '+s[0]+'</h2><p>'+s[1]+'</p>').join("")+'<div class="notice" style="margin:2rem 0">This content is general education, not personal financial, credit or legal advice. Your circumstances and the applicable rules matter.</div>'+btn("/guides","Back to guides","outline")+'</div><aside class="aside-card"><h3>Keep the next step simple.</h3><p>Use our illustrative tools or read another guide before committing to a financial product.</p>'+btn("/tools","Try money tools")+'</aside></div></section>';
 shell(content);
}
function toolsPage(){
 shell(pageHero("FREE PLANNING TOOLS","Turn the numbers into a clearer picture.","Illustrative tools for learning and planning. No financial information leaves your browser.","≈")+
 '<section class="section white"><div class="container"><div class="tool-panels"><div class="tool-panel"><span class="pill">Repayment illustration</span><h3 style="margin-top:1rem">What might a repayment look like?</h3><p>Adjust the example loan size, term and annual interest rate. Figures exclude fees, insurance and provider-specific terms.</p><div class="field"><div class="range-row"><label for="amount-range">Loan amount</label><output id="amount-out">'+money(35000)+'</output></div><input class="range" id="amount-range" type="range" min="1000" max="200000" value="35000" step="1000"></div><div class="field"><div class="range-row"><label for="term-range">Repayment period</label><output id="term-out">36 months</output></div><input class="range" id="term-range" type="range" min="6" max="72" value="36" step="6"></div><div class="field"><div class="range-row"><label for="rate-range">Illustrative annual interest</label><output id="rate-out">18%</output></div><input class="range" id="rate-range" type="range" min="5" max="35" value="18" step="1"></div></div><div class="tool-output" aria-live="polite"><small>Estimated monthly repayment</small><div class="big" id="repayment-val">—</div><div class="line"><span>Illustrative total repayments</span><b id="total-val">—</b></div><div class="line"><span>Illustrative interest</span><b id="interest-val">—</b></div><p class="small" style="color:#c5e2da;margin:1rem 0 0">Not a quote, APR disclosure, eligibility assessment or lending recommendation. Actual pricing and fees may differ.</p></div></div>'+
 '<div class="tool-panels" style="margin-top:2rem"><div class="tool-panel"><span class="pill">Monthly budget snapshot</span><h3 style="margin-top:1rem">How much breathing room is left?</h3><p>Enter rough monthly amounts. This simple calculation does not determine affordability for credit.</p><form id="budget-form"><div class="field"><label for="budget-income">Take-home income (R)</label><input class="input" type="number" id="budget-income" min="0" step="100" value="20000" required></div><div class="field"><label for="budget-essentials">Essentials & regular spending (R)</label><input class="input" type="number" id="budget-essentials" min="0" step="100" value="12500" required></div><div class="field"><label for="budget-debt">Existing repayments (R)</label><input class="input" type="number" id="budget-debt" min="0" step="100" value="4500" required></div><button type="submit" class="button primary">Update budget</button></form></div><div class="tool-output" aria-live="polite"><small>Estimated monthly amount remaining</small><div class="big" id="budget-left">—</div><div id="budget-interpret"></div><p class="small" style="color:#c5e2da;margin-top:1rem">An educational snapshot only. Irregular expenses, emergencies and individual circumstances also matter.</p></div></div></div></section>'+
 '<section class="section compact mint-bg"><div class="container">'+heading("USEFUL NEXT READS","Understand the numbers behind the choices.")+'<div class="grid cols-3">'+guideCards(GUIDES.slice(0,3))+'</div></div></section>');
 const updater=()=>{
 let p=Number($("#amount-range").value),n=Number($("#term-range").value),r=Number($("#rate-range").value)/1200;
 let repayment=r===0?p/n:p*r/(1-Math.pow(1+r,-n));
 $("#amount-out").textContent=money(p);$("#term-out").textContent=n+" months";$("#rate-out").textContent=(r*1200).toFixed(0)+"%";
 $("#repayment-val").textContent=money(Math.round(repayment));$("#total-val").textContent=money(Math.round(repayment*n));$("#interest-val").textContent=money(Math.round(repayment*n-p));
 };
 ["amount-range","term-range","rate-range"].forEach(id=>$("#"+id).addEventListener("input",updater));updater();
 const updateBudget=e=>{if(e)e.preventDefault();let f=$("#budget-form");if(!f.reportValidity())return;let income=Number($("#budget-income").value),ess=Number($("#budget-essentials").value),debt=Number($("#budget-debt").value),left=income-ess-debt;
 $("#budget-left").textContent=(left<0?"−":"")+money(Math.abs(left));$("#budget-interpret").innerHTML='<div class="notice '+(left<0?"warn":"")+'">'+(left<0?"Your listed costs exceed your listed income. Consider reviewing your budget and seeking appropriate advice before borrowing.":left<income*.1?"There is little room for unexpected expenses. Review the numbers carefully before adding a new commitment.":"This is an illustrative remainder. Keep room for irregular costs and savings before deciding on credit.")+'</div>';};
 $("#budget-form").addEventListener("submit",updateBudget);updateBudget();
}
let wizardStep=0,wizardData={purpose:"loan"};
function applyPage(){wizardStep=0;wizardData={purpose:"loan"};shell(pageHero("ENQUIRY JOURNEY DEMO","A clearer application journey.","Try the steps and see how a proper loan or debt-help enquiry should be explained. Nothing is submitted.","↗")+
 '<section class="section white"><div class="container"><div class="wizard-wrap"><div class="wizard-top"><span class="pill dark">Interactive preview</span><h2 style="margin-top:1rem">Tell us what you want to explore.</h2><p>No ID numbers, banking passwords or document uploads. Data is not transmitted or saved.</p></div><div class="progress-track"><div class="progress-fill" id="wizard-progress" style="width:25%"></div></div><div class="wizard-body" id="wizard-body"></div></div><div style="max-width:980px;margin:1.5rem auto">'+sharedQuestionNote+'</div></div></section>');drawWizard();}
function drawWizard(){
 let box=$("#wizard-body");$("#wizard-progress").style.width=(wizardStep+1)*25+"%";
 if(wizardStep===0){
 box.innerHTML='<p class="eyebrow">STEP 1 OF 4</p><h3>Which path are you exploring?</h3><p class="muted">Please choose intentionally. These are different types of information.</p><div class="choice-grid" role="group" aria-label="Choose purpose"><label class="choice"><input type="radio" name="purpose" value="loan" '+(wizardData.purpose==="loan"?"checked":"")+'> Loan options and borrowing</label><label class="choice"><input type="radio" name="purpose" value="debt" '+(wizardData.purpose==="debt"?"checked":"")+'> Debt support or review</label></div><div class="notice" style="margin-top:1.4rem">A loan is a new credit commitment. Debt review is a formal process handled by a registered debt counsellor. Choosing one does not enrol you in the other.</div><div class="wizard-footer"><span class="tag">Preview, not an application</span><button type="button" class="button primary" id="wiz-next">Continue ↗</button></div>';
 } else if(wizardStep===1){
 box.innerHTML='<p class="eyebrow">STEP 2 OF 4</p><h3>'+ (wizardData.purpose==="loan"?"A few details about the loan you are considering.":"A broad picture of your existing commitments.")+'</h3><p class="muted">Example details only. Use fictional figures for this demo.</p><form id="wiz-form"><div class="field-grid">'+
 (wizardData.purpose==="loan"?'<div class="field"><label for="wiz-amount">Amount you want to explore (R)</label><input id="wiz-amount" name="amount" class="input" type="number" min="500" max="500000" required value="'+(wizardData.amount||"25000")+'"><span>Illustration only, not a quote.</span></div>':'<div class="field"><label for="wiz-amount">Approximate total existing debt (R)</label><input id="wiz-amount" name="amount" class="input" type="number" min="0" max="5000000" required value="'+(wizardData.amount||"50000")+'"></div>')+
 '<div class="field"><label for="wiz-income">Monthly take-home income (R)</label><input id="wiz-income" name="income" class="input" type="number" min="0" max="10000000" required value="'+(wizardData.income||"20000")+'"></div>'+
 '<div class="field"><label for="wiz-employment">Employment status</label><select id="wiz-employment" name="employment" required><option value="">Please choose</option>'+["Employed","Self-employed","Pensioner","Not currently working","Other"].map(x=>'<option '+(wizardData.employment===x?"selected":"")+'>'+x+'</option>').join("")+'</select></div>'+
 '<div class="field"><label for="wiz-review">Currently under debt review?</label><select id="wiz-review" name="review" required><option value="">Please choose</option>'+["Yes","No","Not sure"].map(x=>'<option '+(wizardData.review===x?"selected":"")+'>'+x+'</option>').join("")+'</select></div></div></form>'+
 '<div class="notice">Your answer about debt review is used only to tailor this demonstration. No information is sent to any lender or debt counsellor.</div><div class="wizard-footer"><button class="button outline" id="wiz-back">Back</button><button class="button primary" id="wiz-next">Continue ↗</button></div>';
 } else if(wizardStep===2){
 box.innerHTML='<p class="eyebrow">STEP 3 OF 4</p><h3>How a real service would request contact permission.</h3><p class="muted">This is a form-validation demonstration. Use example information, not your real identity.</p><form id="wiz-form"><div class="field-grid"><div class="field"><label for="wiz-name">Example name</label><input class="input" id="wiz-name" name="name" type="text" autocomplete="off" minlength="2" maxlength="80" required placeholder="Demo User"></div><div class="field"><label for="wiz-email">Example email address</label><input class="input" id="wiz-email" name="email" type="email" autocomplete="off" maxlength="120" required placeholder="demo@example.com"></div><div class="field"><label for="wiz-phone">Example mobile number</label><input class="input" id="wiz-phone" name="phone" type="tel" inputmode="tel" autocomplete="off" pattern="[0-9+() -]{9,18}" required placeholder="071 000 0000"></div></div><label class="check-row"><input type="checkbox" name="serviceConsent" required> I understand that this is a local interface preview and no enquiry or personal details will be submitted.</label><label class="check-row"><input type="checkbox" name="marketing"> Illustrative optional marketing consent (unticked by default; no marketing is sent).</label></form><div class="notice warn">No real lead collection, partner sharing or marketing is operational. A live form will require identified recipients, a verified privacy notice, lawful consent and secure backend processing.</div><div class="wizard-footer"><button class="button outline" id="wiz-back">Back</button><button class="button primary" id="wiz-next">Complete demo ↗</button></div>';
 } else {
 let isDebt=wizardData.purpose==="debt";
 box.innerHTML='<div class="result"><span class="pill">Demo complete</span><h3 style="margin-top:1rem">You have completed the preview.</h3><p><strong>No application was submitted.</strong> No information was stored or sent, and no approval or debt-review assessment has taken place.</p><p>The path you selected was: <strong>'+(isDebt?"Debt support information":"Loan information")+'</strong>.</p><p>'+ (isDebt?"For formal debt review, verify an NCR-registered debt counsellor and understand the process before signing.":"For lending, verify the actual credit provider and compare the full cost before accepting a quote.")+'</p><div class="actions">'+btn(isDebt?"/debt-review":"/personal-loans","Read the guide","primary")+btn("/tools","Use money tools","outline")+'<button type="button" class="button outline" id="wiz-restart">Start again</button></div></div>';
 }
 if($("#wiz-next"))$("#wiz-next").addEventListener("click",()=>{
 if(wizardStep===0){wizardData.purpose=$('input[name="purpose"]:checked').value}
 if(wizardStep===1||wizardStep===2){let f=$("#wiz-form");if(!f.reportValidity())return; if(wizardStep===1){wizardData.amount=f.elements.amount.value;wizardData.income=f.elements.income.value;wizardData.employment=f.elements.employment.value;wizardData.review=f.elements.review.value;}else{wizardData.exampleContactProvided=true;}}
 wizardStep=Math.min(3,wizardStep+1);drawWizard();});
 if($("#wiz-back"))$("#wiz-back").addEventListener("click",()=>{wizardStep=Math.max(0,wizardStep-1);drawWizard()});
 if($("#wiz-restart"))$("#wiz-restart").addEventListener("click",()=>{wizardStep=0;wizardData={purpose:"loan"};drawWizard()});
}
function aboutPage(){
 shell(pageHero("ABOUT MONEYSA","A simpler way to understand money choices.","An original South African concept for clearer financial information, practical tools and transparent enquiry journeys.","m")+
 '<section class="section white"><div class="container content-grid"><div class="prose"><h2>Why MoneySA is being built</h2><p>People often arrive at financial websites with one question and discover a maze of unfamiliar terms. MoneySA is designed to explain choices plainly before asking anyone to take the next step.</p><p>Our current preview covers personal borrowing, debt consolidation, formal debt review, car insurance and phone finance, supported by calculators and accessible guides.</p><h2>What this service is today</h2><p>MoneySA is currently a website concept and demonstration. It does not operate as a lender, credit provider, debt counsellor, insurance intermediary, loan broker or referral platform. We do not claim registered partners or approval rates.</p><h2>What needs to happen before launch</h2><p>A business entity and its public details must be verified, any relevant regulatory positions confirmed, recipient relationships documented and secure, auditable data processing implemented. The public-facing privacy notice and terms will then be finalised to describe the real service.</p></div><aside class="aside-card"><h3>Our guiding principles</h3><p>Clear product labels. Honest eligibility information. Visible costs. Separate consent for marketing. No pretending a form is a loan approval.</p>'+btn("/guides","Read our guides")+'</aside></div></section>'+
 '<section class="section compact mint-bg"><div class="container">'+heading("THE DIFFERENCE","Information first. Pressure never.")+'<div class="grid cols-3"><div class="feature-card"><div class="symbol">◎</div><h3>Know the destination</h3><p>You should know which financial service you are exploring before you share details.</p></div><div class="feature-card"><div class="symbol">≈</div><h3>See the trade-offs</h3><p>A lower instalment does not always mean a cheaper decision.</p></div><div class="feature-card"><div class="symbol">✓</div><h3>Keep control</h3><p>Consent should be understandable, specific and optional for marketing.</p></div></div></div></section>');
}
function contactPage(){
 shell(pageHero("CONTACT MONEYSA","Questions deserve real answers.","This preview demonstrates a contact form, but a verified MoneySA contact address and secure enquiry destination have not yet been connected.","✉")+
 '<section class="section white"><div class="container contact-grid"><div><p class="eyebrow">A NOTE BEFORE YOU WRITE</p><h2>Start with the question.</h2><p class="lead">Whether you are asking about the website, a financial topic or a future partnership, the right contact route will be published once the business details are verified.</p><div class="contact-card"><h3>Currently in preview</h3><p>No message delivery is connected. Please do not use this demonstration to send sensitive information, ID numbers, banking details or personal documents.</p><p><strong>Registered business and contact information:</strong> pending owner verification before launch.</p></div></div><div class="tool-panel"><h3>Test the contact form</h3><p>Try the required fields and see the validation. The message stays on this device.</p><form id="contact-form"><div class="field"><label for="contact-name">Name</label><input id="contact-name" name="name" class="input" type="text" required maxlength="80" placeholder="Demo User"></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" name="email" class="input" type="email" required placeholder="demo@example.com"></div><div class="field"><label for="contact-subject">Subject</label><select id="contact-subject" name="subject" required><option value="">Choose a topic</option><option>Website question</option><option>Financial information</option><option>Business enquiry</option></select></div><div class="field"><label for="contact-message">Message</label><textarea id="contact-message" name="message" rows="4" required maxlength="1000" placeholder="Use an example message for this preview."></textarea></div><label class="check-row"><input type="checkbox" required> I understand this form is a demonstration and nothing will be sent.</label><button class="button primary" type="submit">Test form validation</button><p id="contact-feedback" class="form-note" role="status" style="margin-top:1rem"></p></form></div></div></section>');
 $("#contact-form").addEventListener("submit",e=>{e.preventDefault();if(e.currentTarget.reportValidity()){$("#contact-feedback").textContent="Validation passed. This was a demonstration: no message was sent, saved or forwarded.";$("#contact-feedback").style.color="var(--teal)"}});
}
function privacyPage(){
 shell(pageHero("DRAFT PRIVACY NOTICE","Your information deserves clear boundaries.","This draft explains the demo's behaviour and identifies the details still required before collecting real enquiries.","◎")+
 '<section class="section white"><div class="container content-grid"><article class="prose"><div class="notice warn">PRE-LAUNCH DRAFT · The responsible party, physical contact details, Information Officer and lawful recipient list have not been supplied or verified. This is not a final POPIA notice for live collection.</div><h2>1. What this preview does</h2><p>Interactive calculator inputs, demo questionnaire fields and test contact-form entries are processed in your browser to display immediate results. The website code does not submit them to a server, create lead records, send emails or share them with third parties.</p><h2>2. What we do not request</h2><p>The preview does not request South African ID numbers, banking credentials, copies of payslips or supporting financial documents. Avoid entering your actual personal information into any demo field.</p><h2>3. Future collection requires notice</h2><p>Before any live enquiry collection begins, MoneySA must identify the responsible legal entity, purpose for collection, recipients, retention periods, security measures, complaint routes, and any cross-border transfers. The final notice must explain how to access, correct or request deletion of information where applicable.</p><h2>4. Marketing is separate</h2><p>Any future marketing consent must be requested separately from service enquiries, left unticked by default where appropriate and accompanied by a practical opt-out mechanism. This preview does not send marketing communications.</p><h2>5. Third-party services</h2><p>This preview requests web fonts from Google Fonts. Hosting infrastructure may process ordinary technical request data such as IP addresses and server logs; specific operational settings must be confirmed with the hosting account owner before launch.</p><h2>6. Contact and complaints</h2><p>MoneySA’s verified legal contact and Information Officer details must be inserted before any live collection. Information Regulator guidance is available at <a href="https://inforegulator.org.za/" target="_blank" rel="noopener">inforegulator.org.za</a>.</p><h2>7. Status of this notice</h2><p>Draft dated 1 November 2026. This notice is intentionally marked incomplete and is not a substitute for legal and operational review.</p></article><aside class="aside-card"><h3>No hidden lead capture.</h3><p>MoneySA’s preview forms run locally. They do not send credit or debt-review information to third parties.</p>'+btn("/contact","Contact page")+'</aside></div></section>');
}
function termsPage(){
 shell(pageHero("DRAFT WEBSITE TERMS","Know what this site can and cannot do.","Plain-language terms for this demonstration, pending a verified operator and legal review.","≡")+
 '<section class="section white"><div class="container content-grid"><article class="prose"><div class="notice warn">PRE-LAUNCH DRAFT · Add the correct business identity, address, complaints contact and legal review before going live.</div><h2>1. Purpose</h2><p>MoneySA currently provides general educational content, calculators and demonstration forms. It does not provide personalised financial advice, credit or insurance products, debt counselling or live referrals.</p><h2>2. No applications or offers</h2><p>Completing a preview form does not create an application, contract, credit score enquiry, approval, counselling appointment or legal debt-review record. No money is advanced through this website.</p><h2>3. Calculators</h2><p>Calculators are simplified illustrations. They do not include all possible charges, taxes, insurance costs or individual circumstances and must not be treated as financial quotations or affordability assessments.</p><h2>4. Content</h2><p>Information is general and may become outdated as laws and commercial products change. Verify details directly with relevant registered providers or qualified advisers before acting.</p><h2>5. Your information</h2><p>Do not input actual ID numbers, bank credentials, confidential documents or other sensitive data into demonstration forms. See the <a data-link href="/privacy">draft privacy notice</a>.</p><h2>6. Third-party links</h2><p>External references are provided for context. They are not endorsements or proof of any commercial relationship.</p><h2>7. Launch requirements</h2><p>Commercial representations, product provider relationships, disclosures, contact channels and consumer complaints processes must be verified before this preview becomes an operational marketplace.</p><h2>8. Status</h2><p>Draft dated 1 November 2026, subject to business-owner and legal review.</p></article><aside class="aside-card"><h3>Questions about a topic?</h3><p>Start in our guides or use the simple calculation tools.</p>'+btn("/guides","Information hub")+'</aside></div></section>');
}
